import json
from pathlib import Path
from core.project_engine.models import ProjectDefinition
from generators.terrain.heightfield import generate_heightfield
PROJECT='''config_version=5\n[application]\nconfig/name="PGF Generated World"\nrun/main_scene="res://main.tscn"\n[display]\nwindow/size/viewport_width=1280\nwindow/size/viewport_height=720\n[rendering]\nrenderer/rendering_method="gl_compatibility"\nrenderer/rendering_method.mobile="gl_compatibility"\n'''
SCENE='''[gd_scene load_steps=2 format=3]\n[ext_resource type="Script" path="res://scripts/main.gd" id="1"]\n[node name="PGFWorld" type="Node3D"]\nscript = ExtResource("1")\n'''
MAIN='''extends Node3D\nconst Terrain = preload("res://scripts/terrain.gd")\nconst Player = preload("res://scripts/player.gd")\nfunc _ready() -> void:\n    var data = JSON.parse_string(FileAccess.get_file_as_string("res://pgf_world.json"))\n    var terrain = Terrain.new()\n    terrain.name = "GeneratedTerrain"\n    terrain.configure(data)\n    add_child(terrain)\n    var sun = DirectionalLight3D.new()\n    sun.rotation_degrees = Vector3(-48, -28, 0)\n    sun.light_energy = 1.2\n    add_child(sun)\n    var player = CharacterBody3D.new()\n    player.name = "Player"\n    player.set_script(Player)\n    player.position = Vector3(0, 16, 0)\n    add_child(player)\n    var camera = Camera3D.new()\n    camera.position = Vector3(0, 3.5, 7)\n    camera.rotation_degrees = Vector3(-12, 180, 0)\n    player.add_child(camera)\n    camera.current = true\n'''
PLAYER='''extends CharacterBody3D\n@export var move_speed: float = 6.0\n@export var jump_velocity: float = 4.5\nvar gravity: float = ProjectSettings.get_setting("physics/3d/default_gravity")\nfunc _ready() -> void:\n    var shape = CapsuleShape3D.new()\n    shape.radius = 0.45\n    shape.height = 1.8\n    var collision = CollisionShape3D.new()\n    collision.shape = shape\n    add_child(collision)\n    var mesh = MeshInstance3D.new()\n    var capsule = CapsuleMesh.new()\n    capsule.radius = 0.45\n    capsule.height = 1.8\n    mesh.mesh = capsule\n    add_child(mesh)\nfunc _physics_process(delta: float) -> void:\n    if not is_on_floor(): velocity.y -= gravity * delta\n    if Input.is_action_just_pressed("ui_accept") and is_on_floor(): velocity.y = jump_velocity\n    var input_dir = Input.get_vector("ui_left","ui_right","ui_up","ui_down")\n    var direction = (global_transform.basis * Vector3(input_dir.x,0,input_dir.y)).normalized()\n    velocity.x = direction.x * move_speed\n    velocity.z = direction.z * move_speed\n    move_and_slide()\n'''
TERRAIN='''extends MeshInstance3D\nfunc configure(data: Dictionary) -> void:\n    var heights: Array = data.get("heights", [])\n    if heights.is_empty(): return\n    var rows=heights.size()\n    var cols=heights[0].size()\n    var width=float(data.get("width",96))\n    var depth=float(data.get("depth",96))\n    var vertices=PackedVector3Array()\n    var indices=PackedInt32Array()\n    for z in range(rows):\n        for x in range(cols):\n            vertices.append(Vector3((float(x)/(cols-1)-0.5)*width,float(heights[z][x]),(float(z)/(rows-1)-0.5)*depth))\n    for z in range(rows-1):\n        for x in range(cols-1):\n            var a=z*cols+x\n            var b=a+1\n            var c=a+cols\n            var d=c+1\n            indices.append_array(PackedInt32Array([a,c,b,b,c,d]))\n    var arrays=[]\n    arrays.resize(Mesh.ARRAY_MAX)\n    arrays[Mesh.ARRAY_VERTEX]=vertices\n    arrays[Mesh.ARRAY_INDEX]=indices\n    var generated=ArrayMesh.new()\n    generated.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES,arrays)\n    mesh=generated\n    var body=StaticBody3D.new()\n    var collision=CollisionShape3D.new()\n    var shape=ConcavePolygonShape3D.new()\n    shape.set_faces(vertices)\n    collision.shape=shape\n    body.add_child(collision)\n    add_child(body)\n    var material=StandardMaterial3D.new()\n    material.albedo_color=Color(0.22,0.31,0.27)\n    material.roughness=1.0\n    material_override=material\n'''
def assemble_godot_project(definition: ProjectDefinition,destination: Path) -> Path:
    destination.mkdir(parents=True,exist_ok=True); (destination/"scripts").mkdir(exist_ok=True)
    heights=generate_heightfield(definition.project.seed,definition.world.width,definition.world.depth,definition.world.resolution,definition.world.amplitude,definition.world.frequency)
    (destination/"pgf_world.json").write_text(json.dumps({"seed":definition.project.seed,"width":definition.world.width,"depth":definition.world.depth,"heights":heights}),encoding="utf-8")
    (destination/"project.godot").write_text(PROJECT,encoding="utf-8"); (destination/"main.tscn").write_text(SCENE,encoding="utf-8")
    for name,body in [("main.gd",MAIN),("player.gd",PLAYER),("terrain.gd",TERRAIN)]: (destination/"scripts"/name).write_text(body,encoding="utf-8")
    (destination/"pgf_build.json").write_text(json.dumps({"project_id":definition.id,"generator_version":"0.1.0"},indent=2),encoding="utf-8")
    return destination
